python3 - <<'EOF'
import os, signal, subprocess, time
# kill everything on 8805
for pid in subprocess.run(['pgrep','-f','fake_'], capture_output=True, text=True).stdout.split():
    try: os.kill(int(pid), signal.SIGKILL)
    except ProcessLookupError: pass
time.sleep(1)
lines = open('/proc/net/udp').read().splitlines()[1:]
holders = [l.split()[9] for l in lines if int(l.split()[1].split(':')[1], 16) == 8805]
print('8805 holders after cleanup:', holders if holders else 'FREE')
# find process owning the inode if busy
if holders:
    import glob
    for pid_dir in glob.glob('/proc/[0-9]*'):
        try:
            for fd in glob.glob(pid_dir + '/fd/*'):
                try:
                    if os.readlink(fd).startswith('socket:[') and holders[0] in os.readlink(fd):
                        print('held by pid', pid_dir, open(pid_dir+'/cmdline').read()[:120])
                        break
                except OSError: continue
        except OSError: continue
EOF

